"""Local acceptance: real FERRO GPU render, native clicks/drag, files, persistence.
Uses the project's existing Chrome pipe harness; no server or network port.
"""
import base64,json,pathlib,tempfile,time
from browser_support import Browser,ROOT
OUT=ROOT/'work/editor-validation';OUT.mkdir(parents=True,exist_ok=True)
checks=[]
def check(name,condition):
    assert condition,name
    checks.append(name)
def click(b,selector):
    point=b.ev('(()=>{const e=document.querySelector('+json.dumps(selector)+');e.scrollIntoView({block:"nearest"});const r=e.getBoundingClientRect();return {x:r.x+r.width/2,y:r.y+r.height/2};})()')
    for kind in ['mousePressed','mouseReleased']:b.cmd('Input.dispatchMouseEvent',{'type':kind,**point,'button':'left','clickCount':1})
def value(b,selector,value):
    b.ev('(()=>{const e=document.querySelector('+json.dumps(selector)+');e.value='+json.dumps(str(value))+';e.dispatchEvent(new Event("change",{bubbles:true}));})()')
def snapshot(b):return b.ev('FerroEditor.snapshot()')
def ready(b):b.wait('globalThis.FerroEditor?.snapshot().frames>0 || document.querySelector("#status")?.classList.contains("error")');assert b.ev('!!globalThis.FerroEditor && !FerroEditor.snapshot().failed'),b.ev('document.querySelector("#status").textContent')
report={'checks':checks,'scope':'Local Chrome on Mac; no deployed game changed.'}
with Browser() as b, tempfile.TemporaryDirectory(prefix='ferro-downloads-') as downloads:
    b.cmd('Page.addScriptToEvaluateOnNewDocument',{'source':'globalThis.__editorErrors=[];addEventListener("error",e=>__editorErrors.push(e.message));addEventListener("unhandledrejection",e=>__editorErrors.push(String(e.reason)));'})
    b.c.envoyer('Browser.setDownloadBehavior',{'behavior':'allow','downloadPath':downloads})
    url=(ROOT/'editor/index.html').as_uri();b.cmd('Page.navigate',{'url':url});ready(b)
    start=snapshot(b);check('real WebGL2 backend',start['stats']['backend']=='webgl2');check('procedural scene has 25 instances',len(start['meshes'])==25)
    b.wait('FerroEditor.snapshot().frames>0');(OUT/'atelier-webgl2.png').write_bytes(base64.b64decode(b.cmd('Page.captureScreenshot',{'format':'png'})['data']))
    value(b,'[aria-label="Position · m X"]',1.6);check('inspector moves selected source',snapshot(b)['recipe']['nodes'][6]['p'][0]==1.6)
    click(b,'#undo');check('undo restores position',snapshot(b)['recipe']['nodes'][6]['p'][0]==.6)
    click(b,'#redo');check('redo restores edit',snapshot(b)['recipe']['nodes'][6]['p'][0]==1.6)
    click(b,'#add');check('primitive added',len(snapshot(b)['meshes'])==26)
    click(b,'#repeat');check('repeat generates copies',len(snapshot(b)['meshes'])==29)
    # The repeat inspector exposes a single numeric count input outside vectors.
    value(b,'#properties .field input[type=number]:not([aria-label])',6);check('repeat count drives instances',len(snapshot(b)['meshes'])==31)
    before=snapshot(b)['recipe'];value(b,'#properties .field input[type=number]:not([aria-label])',999);check('invalid edit is atomic',snapshot(b)['recipe']==before)
    click(b,'#duplicate');check('recursive copy produces independent procedure',len(snapshot(b)['meshes'])==37)
    click(b,'#undo');check('undo copied subgraph',len(snapshot(b)['meshes'])==31)
    # Native selection and ground-plane translation in the centre of the quay.
    click(b,'#move-tool');rect=b.ev('(()=>{const r=document.querySelector("canvas").getBoundingClientRect();return {x:r.x+r.width*.5,y:r.y+r.height*.6};})()')
    b.cmd('Input.dispatchMouseEvent',{'type':'mousePressed',**rect,'button':'left','clickCount':1})
    selected=b.ev('FerroEditor.snapshot().selected');pre=snapshot(b)['recipe'];
    b.cmd('Input.dispatchMouseEvent',{'type':'mouseMoved','x':rect['x']+25,'y':rect['y']+10,'button':'left','buttons':1})
    b.cmd('Input.dispatchMouseEvent',{'type':'mouseReleased','x':rect['x']+25,'y':rect['y']+10,'button':'left','clickCount':1})
    check('native viewport picking',selected is not None);check('native drag records a procedural transform',snapshot(b)['recipe']!=pre)
    click(b,'#undo');check('one undo reverses entire drag',snapshot(b)['recipe']==pre)
    # Material independent copy, mutation and undo.
    click(b,'#material-new');n=snapshot(b);check('independent material added',len(n['recipe']['materials'])==6)
    value(b,'#material-properties input[type=color]','#cc4411');check('material parameters affect meshes',any(m['color']==[.8,68/255,17/255] for m in snapshot(b)['meshes']))
    value(b,'#seed',456);saved=snapshot(b);b.cmd('Page.reload');ready(b);check('reload restores recipe exactly',snapshot(b)['recipe']==saved['recipe']);check('reload regenerates same meshes',snapshot(b)['meshes']==saved['meshes'])
    # File download exercises the real export buttons and their generated bytes.
    click(b,'#save');click(b,'#export');end=time.monotonic()+10
    while len(list(pathlib.Path(downloads).glob('*')))<2 and time.monotonic()<end:time.sleep(.05)
    json_file=next(pathlib.Path(downloads).glob('*.json'));module_file=next(pathlib.Path(downloads).glob('*.mjs'))
    exported=json.loads(json_file.read_text());check('JSON download preserves recipe',exported==saved['recipe']);check('JS download retains generator', 'export default function generate' in module_file.read_text())
    click(b,'#new-scene');check('empty scene authoring works',len(snapshot(b)['meshes'])==0)
    doc=b.cmd('DOM.getDocument');file_id=b.cmd('DOM.querySelector',{'nodeId':doc['root']['nodeId'],'selector':'#file'})['nodeId'];b.cmd('DOM.setFileInputFiles',{'nodeId':file_id,'files':[str(json_file)]});b.wait('FerroEditor.snapshot().meshes.length>0');check('native file import roundtrip',snapshot(b)['meshes']==saved['meshes'])
    invalid=pathlib.Path(downloads)/'invalid.json';invalid.write_text('{"format":"evil"}')
    b.cmd('DOM.setFileInputFiles',{'nodeId':file_id,'files':[str(invalid)]});b.wait('document.querySelector("#status")?.classList.contains("error")');check('invalid file leaves scene untouched',snapshot(b)['recipe']==saved['recipe'])
    click(b,'#visit');check('free visit active',snapshot(b)['visit']);b.cmd('Input.dispatchKeyEvent',{'type':'keyDown','key':'w','code':'KeyW'});time.sleep(.5);b.cmd('Input.dispatchKeyEvent',{'type':'keyUp','key':'w','code':'KeyW'});b.cmd('Input.dispatchKeyEvent',{'type':'keyDown','key':'Escape','code':'Escape'});check('escape returns to authoring',not snapshot(b)['visit'])
    b.ev('globalThis.loss=FerroEditor.renderer.gl.getExtension("WEBGL_lose_context");loss.loseContext();true');b.wait('FerroEditor.renderer.stats.contextLost');b.ev('loss.restoreContext();true');b.wait('!FerroEditor.renderer.stats.contextLost');before_frames=snapshot(b)['frames'];click(b,'#overview');b.wait('FerroEditor.snapshot().frames>'+str(before_frames));check('context restoration preserves procedural scene',snapshot(b)['meshes']==saved['meshes'])
    check('no browser exceptions',not b.ev('__editorErrors'));check('no GL error after editing',b.ev('FerroEditor.renderer.gl.getError()')==0)
    report['webgl2']={k:v for k,v in snapshot(b)['stats'].items() if isinstance(v,(str,int,float,bool))}
    # Source and self-contained artifact both exercise actual native backends.
    b.cmd('Page.navigate',{'url':(ROOT/'dist/ferro-editor.html').as_uri()+'?renderer=webgpu'});ready(b)
    standalone=snapshot(b);report['standaloneBackend']=standalone['stats']['backend'];check('standalone HTML renders',standalone['frames']>0)
    if standalone['stats']['backend']=='webgpu':check('native WebGPU procedural render',not standalone['failed'])
    else:report['webgpuFallback']=standalone['stats'].get('fallbackReason')
    check('standalone no exceptions',not b.ev('__editorErrors'))
    (OUT/'atelier-standalone.png').write_bytes(base64.b64decode(b.cmd('Page.captureScreenshot',{'format':'png'})['data']))
    report['standalone']={k:v for k,v in standalone['stats'].items() if isinstance(v,(str,int,float,bool))}
(OUT/'browser-report.json').write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n');print(json.dumps(report,ensure_ascii=False))
